#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const ll MOD = 998244353;
ll f[200001];

ll binpow(ll a, ll b) {
    if (b == 0) return 1;

    ll res = binpow(a, b / 2);
    res = res * res % MOD;

    if (b % 2) {
        res = res * a % MOD;
    }

    return res;
}

int main() {
    int n, m;
    cin >> n >> m;

    f[0] = 1;
    for (int i = 1; i <= 200000; i++) {
        f[i] = f[i - 1] * i % MOD;
    }

    ll val = 0;
    for (int i = n - 2; i <= m - 1; i++) {
        ll xx = f[i];
        xx = xx * binpow(f[n - 2], MOD - 2) % MOD;
        xx = xx * binpow(f[i - n + 2], MOD - 2) % MOD;
        val = (val + xx) % MOD;
    }

    ll ans = 0;

    for (int i = 1; i < n - 1; i++) {
        ll xx = f[n - 3];
        xx = xx * binpow(f[i - 1], MOD - 2) % MOD;
        xx = xx * binpow(f[n - i - 2], MOD - 2) % MOD;
        xx = xx * (n - 2) % MOD;
        xx = xx * val % MOD;
        ans = (ans + xx) % MOD;
    }

    cout << ans << '\n';
    return 0;
}

